parameters.jsCode:
const trigger = $('Gmail Trigger').item.json;
let raw = '';
try {
  raw = $json.choices[0].message.content || '';
} catch (e) {
  raw = '';
}

// Extraction robuste du JSON
let parsed;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error("Pas de JSON trouvé");
  }
} catch (e) {
  parsed = { is_client: true, urgency: 'normale', summary: 'À vérifier manuellement (analyse IA échouée)', action_needed: '' };
}

// --- NETTOYAGE GMAIL ---

// 1. Extraire UNIQUEMENT l'adresse email pure (enlever le "Nom <...>")
const rawFrom = trigger.From || trigger.from || '';
let fromAddress = rawFrom;
if (rawFrom && rawFrom.value && rawFrom.value[0] && rawFrom.value[0].address) {
    fromAddress = rawFrom.value[0].address;
} else if (typeof rawFrom === 'string') {
    const match = rawFrom.match(/<([^>]+)>/);
    if (match) {
        fromAddress = match[1]; // Ne garde que ce qui est entre < >
    }
}
fromAddress = fromAddress.trim(); // Supprime les espaces autour

// 2. Nettoyer le Thread ID de tout espace invisible
const cleanThreadId = (trigger.threadId || '').trim();

const bodyText = trigger.text || trigger.textPlain || trigger.snippet || '';
const originalSubject = trigger.Subject || trigger.subject || '';

return {
  json: {
    is_client: parsed.is_client === true,
    urgency: parsed.urgency || 'normale',
    summary: parsed.summary || '',
    action_needed: parsed.action_needed || '',
    originalSubject: originalSubject,
    originalFrom: fromAddress,
    originalBody: bodyText,
    threadId: cleanThreadId
  }
};

