parameters.jsCode:
const triage = $('Parser le tri').item.json;
let replyText = '';
try {
  replyText = ($json.choices[0].message.content || '').trim();
} catch (e) {
  replyText = '';
}

const draftBody = replyText;
const internalSummary = `[Résumé interne — ${(triage.urgency || 'normale').toUpperCase()}] ${triage.summary || ''}`;

return {
  json: {
    draftBody,
    internalSummary,
    subject: `Re : ${triage.originalSubject || ''}`,
    to: triage.originalFrom || '',
    threadId: triage.threadId || ''
  }
};
